from typing import Dict, List


def classify_mod8(c: int) -> Dict[str, object]:
    """Pair-sum classifier: given c = N mod 8 (odd), decide what (p+q) mod 8 reveals."""
    units: List[int] = [1, 3, 5, 7]
    assert c in units
    fibres: Dict[int, List[int]] = {}
    for u in units:
        fibres.setdefault((u * (1 + c)) % 8, []).append(u)   # pair sum = u(1+c)
    unordered = all(set(f) <= {f[0], (c * f[0]) % 8} for f in fibres.values())
    ordered = all(len(f) == 1 for f in fibres.values())
    return {"fibres": fibres, "ordered_sufficient": ordered,
            "unordered_sufficient": unordered, "zero_information": len(fibres) == 1}


if __name__ == "__main__":
    for c in [1, 3, 5, 7]:
        print(c, classify_mod8(c))

from typing import Dict, List, Tuple


def determined_precision(ell: int, k: int, separated_only: bool = False) -> int:
    """Largest j <= k such that (p+q, pq) mod ell^k determines {p, q} mod ell^j."""
    m = ell ** k
    buckets: Dict[Tuple[int, int], List[Tuple[int, int]]] = {}
    for p in range(m):
        for q in range(p, m):
            if separated_only and (p - q) % ell == 0:
                continue
            buckets.setdefault(((p + q) % m, (p * q) % m), []).append((p, q))
    best = 0
    for j in range(k + 1):
        mj = ell ** j
        if all(len({tuple(sorted((a % mj, b % mj))) for a, b in pairs}) == 1
               for pairs in buckets.values()):
            best = j
        else:
            break
    return best


if __name__ == "__main__":
    for ell, kmax in [(2, 6), (3, 4), (5, 3)]:
        print(ell, [determined_precision(ell, k) for k in range(1, kmax + 1)],
              [determined_precision(ell, k, True) for k in range(1, kmax + 1)])

